		public global::Dpr.Message.LabelTagDataModel ColorTagAnalysis(global::Nintendo.MessageStudio.Lib.ColorTagInfo colorTagInfo) {
            var tagDataModel = new LabelTagDataModel();
            tagDataModel.patternID = MessageEnumData.TagPatternID.RichText;
            tagDataModel.index = colorTagInfo.Index;
            tagDataModel.tagGroupID = (MessageEnumData.GroupTagID)colorTagInfo.TagGroup;
            tagDataModel.tagID = colorTagInfo.Tag;

            var color = colorTagInfo.Color;
            if (color.R == 0 && color.G == 0 && color.B == 0)
            {
                tagDataModel.strValue = "</color>";
            }
            else
            {
                systemTagStrBuilder.Clear();
                systemTagStrBuilder.Append("<color=#");
                systemTagStrBuilder.Append(color.R.ToString("X2"));
                systemTagStrBuilder.Append(color.G.ToString("X2"));
                systemTagStrBuilder.Append(color.B.ToString("X2"));
                systemTagStrBuilder.Append(color.A.ToString("X2"));
                systemTagStrBuilder.Append(">");
                tagDataModel.strValue = systemTagStrBuilder.ToString();
            }

            return tagDataModel;
        }
		public global::Dpr.Message.LabelTagDataModel FontTagAnalysis(global::Nintendo.MessageStudio.Lib.FontTagInfo fontTagInfo) {
            var tagDataModel = new LabelTagDataModel();
            tagDataModel.patternID = MessageEnumData.TagPatternID.RichText;
            tagDataModel.tagGroupID = (MessageEnumData.GroupTagID)fontTagInfo.TagGroup;
            tagDataModel.tagID = fontTagInfo.Tag;

            int index = fontTagInfo.Index;
            if (index == MessageDataConstants.CLOSE_FONT_TAG_VALUE)
            {
                tagDataModel.strValue = "</font>";
            }
            else
            {
                var fontTagData = MessageFontDataConstants.TEXT_FONT_TABLE[index];
                systemTagStrBuilder.Clear();
                systemTagStrBuilder.Append("<font=");
                systemTagStrBuilder.Append(GetFontFileName(fontTagData.fontFileIndex));
                systemTagStrBuilder.Append(">");
                tagDataModel.strValue = systemTagStrBuilder.ToString();
                tagDataModel.langID = fontTagData.languageId;
            }

            return tagDataModel;
        }
