            return MessageFontDataConstants.FONT_FILE_NAME_ARRAY[fontFileIndex];
        }
		public global::Dpr.Message.LabelTagDataModel SizeTagAnalysis(global::Nintendo.MessageStudio.Lib.SizeTagInfo sizeTagInfo) {
            var tagDataModel = new LabelTagDataModel();
            tagDataModel.patternID = MessageEnumData.TagPatternID.RichText;
            tagDataModel.tagGroupID = (MessageEnumData.GroupTagID)sizeTagInfo.TagGroup;
            tagDataModel.tagID = sizeTagInfo.Tag;

            // StringBuilder.Append(int) 0x286D4B0 (not the ushort overload) → an int local.
            int size = sizeTagInfo.Size;
            if (size == 100)
            {
                tagDataModel.strValue = "</size>";
            }
            else
            {
                systemTagStrBuilder.Clear();
                systemTagStrBuilder.Append("<size=");
                systemTagStrBuilder.Append(size);
                systemTagStrBuilder.Append("%>");
                tagDataModel.strValue = systemTagStrBuilder.ToString();
                tagDataModel.tagParameter = size;
            }

            return tagDataModel;
        }
		private string[] ExtractGrmWords(byte[] tagParams) {
            if (tagParams.Length <= MIN_BYTE_LENGTH)
                return null;

            var encoding = Encoding.Unicode;
            var words = new System.Collections.Generic.List<string>();
            int wordByteLength = GetWordByteLength(tagParams, BYTE_SIZE);
            for (int i = MIN_BYTE_LENGTH; i < tagParams.Length; i += BYTE_SIZE)
            {
                if (wordByteLength > 0)
                {
                    wordStrBuilder.Append(encoding.GetString(tagParams, i, BYTE_SIZE));
                    wordByteLength -= BYTE_SIZE;
                }
                else
                {
                    words.Add(wordStrBuilder.ToString());
                    wordStrBuilder.Clear();
                    wordByteLength = GetWordByteLength(tagParams, i);
                }
            }

            if (wordStrBuilder.Length > 0)
                words.Add(wordStrBuilder.ToString());

            wordStrBuilder.Clear();

            int count = words.Count;
            if (count <= 0)
                return null;

            var result = new string[count];
            for (int i = 0; i < count; i++)
                result[i] = words[i];

            return result;
        }
		private int GetWordByteLength(byte[] tagParams, int startIndex) {
            byteArray[0] = tagParams[startIndex];
            byteArray[1] = tagParams[startIndex + 1];
            return System.BitConverter.ToInt16(byteArray, 0);
        }
